using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation; using Microsoft.Extensions.DependencyInjection; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeQueryIntegrationTests{[Fact]public void Production_di_resolves_catalog_validator_and_preserves_validation(){using var p=KnowledgeQueryFixture.Provider();var catalog=p.GetRequiredService<IAstronomyKnowledgeCatalog>();var validator=p.GetRequiredService<IAstronomyKnowledgeQueryValidator>();Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>());var real=catalog.Snapshot.KnowledgeTypes[0];var cq=new AstronomyKnowledgeCatalogQuery(domains:new([real.Domain!.Value]));var sq=new AstronomyKnowledgeStatementQuery(knowledgeTypes:new([real.KnowledgeTypeId!.Value]));Assert.True(validator.Validate(cq).IsValid);Assert.True(validator.Validate(sq).IsValid);var bad=validator.Validate(new AstronomyKnowledgeStatementQuery(knowledgeTypes:new([Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.AstronomyKnowledgeTypeId.Create("missing")])));Assert.Equal(AstronomyKnowledgeQueryTarget.Statement,bad.Issues[0].Target);Assert.Equal(AstronomyKnowledgeQueryValidationCode.UnknownKnowledgeType,bad.Issues[0].Code);Assert.Null(p.GetService(Type.GetType("Astronomy.MediaFactory.Core.KnowledgeFoundation.Query.IAstronomyKnowledgeQueryEngine, Astronomy.MediaFactory.Core")));}}
